// Shared video-game platform metadata: display labels + Controllercons
// (SIL OFL 1.1) duotone SVG icons, inlined as raw markup (not <img src>) so
// `.ccsvg__primary`/`.ccsvg__secondary` can inherit `currentColor` and match
// light/dark theme automatically. Used by views/soundtracks.js (group
// headers) and views/release.js (the video-game soundtrack badge).
const PLATFORM_LABELS = {
    nes: 'NES', snes: 'SNES', n64: 'Nintendo 64', gamecube: 'GameCube',
    wii: 'Wii', wiiu: 'Wii U', switch: 'Switch',
    gb: 'Game Boy', gbc: 'Game Boy Color', gba: 'Game Boy Advance',
    nds: 'Nintendo DS', '3ds': '3DS',
    ps1: 'PlayStation', ps2: 'PlayStation 2', ps3: 'PlayStation 3',
    ps4: 'PlayStation 4', ps5: 'PlayStation 5', psp: 'PSP', vita: 'PS Vita',
    xbox: 'Xbox', xbox360: 'Xbox 360', xboxone: 'Xbox One', xboxseries: 'Xbox Series',
    pc: 'PC', arcade: 'Arcade', dreamcast: 'Dreamcast', saturn: 'Saturn', genesis: 'Genesis',
    mobile: 'Mobile', ar: 'AR',
};

function platformLabel(p) {
    if (!p) return 'Unknown platform';
    return p.split(',').map(x => PLATFORM_LABELS[x.trim()] || x.trim()).join(' / ');
}

// Controllercons (SIL OFL 1.1) duotone icons, inlined as raw SVG markup
// (not <img src>) so `.ccsvg__primary`/`.ccsvg__secondary` can inherit
// `currentColor` from CSS and match light/dark theme automatically. Only
// covers platforms with an actual distinct controller shape — handhelds,
// PC, arcade, and mobile have no icon here and fall back to the plain-
// text label, same as any platform missing from this map.
